-- Redesign copy (Sept 2026). Safe to re-run.
-- Live server: mysql --default-character-set=utf8mb4 -u<user> -p <db> < database/updates/2026-09-27-redesign.sql
SET NAMES utf8mb4;
ON DUPLICATE KEY UPDATE en = VALUES(en), ar = VALUES(ar);

-- AI & Automation skills (only what projects back up). Skipped if already present.
SELECT * FROM (SELECT 'ai' c, 'LLM integration (Gemini)' e, 'دمج النماذج اللغوية (Gemini)' a, 1 o UNION ALL
               SELECT 'ai', 'Output validation (Zod)', 'التحقق من المخرجات (Zod)', 2 UNION ALL
               SELECT 'ai', 'Grounded generation', 'توليد مقيد بالمصادر', 3 UNION ALL
               SELECT 'ai', 'n8n automation', 'أتمتة n8n', 4 UNION ALL
               SELECT 'ai', 'TensorFlow / transfer learning', 'TensorFlow والتعلم بالنقل', 5) n
WHERE NOT EXISTS (SELECT 1 FROM skills s WHERE s.category = n.c AND s.name_en = n.e);

